# 16.4 — ai được đọc log, chỉ-ghi-thêm (chattr +a), chuỗi băm, băm bằng chứng — trên máy chủ may16 (cong-cu/may.bash len; BASH_ENV=cong-cu/env.bash)
may -u an 'echo sai-mat-khau | sudo -S -k true 2>&1 | tail -1; echo MatKhauLab-15 | sudo -S -k true 2>/dev/null && echo "sudo OK"'
may 'ls -l /var/log/auth.log /var/log/syslog; ls -ld /var/log/journal; getent group adm systemd-journal'
may -u dev 'id; tail -2 /var/log/auth.log; journalctl -q -n 2 --no-pager _COMM=sudo'
may 'usermod -aG adm dev'; may -u dev 'grep "sudo:" /var/log/auth.log | grep -v usermod | head -2 | cut -c1-120'
may 'gpasswd -d dev adm'
may 'mkdir -p /var/log/shop; umask 022; echo "{\"msg\":\"đăng nhập\",\"userId\":\"u_42\",\"email\":\"an@example.com\"}" >> /var/log/shop/app.log; ls -l /var/log/shop/app.log'
may -u dev 'cat /var/log/shop/app.log'
may 'chown root:adm /var/log/shop/app.log; chmod 0640 /var/log/shop/app.log; printf "/var/log/shop/*.log {\n  daily\n  rotate 14\n  compress\n  delaycompress\n  missingok\n  create 0640 root adm\n}\n" > /etc/logrotate.d/shop; logrotate -f /etc/logrotate.d/shop; ls -l /var/log/shop/'
may -u dev 'cat /var/log/shop/app.log.1'
may 'cd /var/log/shop; chattr +a app.log; lsattr app.log; echo "{\"msg\":\"dòng mới\"}" >> app.log && echo "ghi thêm: được"; echo x > app.log; : > app.log; rm app.log; mv app.log app.cu; wc -l app.log'
may 'logrotate -f /etc/logrotate.d/shop 2>&1 | head -3'
may 'chattr -a /var/log/shop/app.log && echo "root gỡ +a: được" && lsattr /var/log/shop/app.log'
may 'cd /tmp; journalctl -q --no-pager -o short-iso _COMM=sudo > sudo.log; wc -l < sudo.log; python3 /lab/toan-ven/chuoi-bam.py ky sudo.log sudo.chuoi.log; cut -c1-150 sudo.chuoi.log | head -3'
may 'cd /tmp; python3 /lab/toan-ven/chuoi-bam.py kiem sudo.chuoi.log'
may 'cd /tmp; sed -i "s/: 1 incorrect password attempt ;/: session opened ;/" sudo.chuoi.log; python3 /lab/toan-ven/chuoi-bam.py kiem sudo.chuoi.log'
may 'cd /tmp; cut -d"|" -f1 sudo.chuoi.log | sed "s/ $//" > sua.log; python3 /lab/toan-ven/chuoi-bam.py ky sua.log sudo.chuoi.log >/dev/null; python3 /lab/toan-ven/chuoi-bam.py kiem sudo.chuoi.log; M=$(python3 /lab/toan-ven/chuoi-bam.py ky sudo.log /dev/null | cut -d" " -f3); python3 /lab/toan-ven/chuoi-bam.py kiem sudo.chuoi.log $M'
may 'mkdir -p /bang-chung && cd /var/log && tar --sort=name -czf /bang-chung/may16-auth-$(date +%Y%m%d).tar.gz auth.log* shop/ && cd /bang-chung && sha256sum *.tar.gz | tee SHA256SUMS && cp -a *.tar.gz /tmp/ban-sao.tar.gz && sha256sum /tmp/ban-sao.tar.gz | cut -c1-20'
